export const modes=['fixed','rl','random','rsi'];
export function rng(s){return()=>{s=(Math.imul(s,1664525)+1013904223)>>>0;return s/4294967296}}
export function maze(seed,hard=false){const r=rng(seed),walls=Array(100).fill(false);for(let i=0;i<100;i++)walls[i]=r()<(hard?.3:.18);walls[0]=walls[99]=false; // carve a winding guaranteed route
let p=0;while(p!==99){walls[p]=false;p+=p%10===9?10:p>=90?1:r()<.5?1:10}walls[99]=false;
if(hard){walls.fill(false);for(let y=1;y<9;y+=2)for(let x=0;x<10;x++)if(x!==(y%4===1?9:0))walls[y*10+x]=true}return walls}
const dirs=[[1,0],[0,1],[-1,0],[0,-1]];
export function observe(w,p,vis,last){const x=p%10,y=p/10|0;return{patch:Array.from({length:25},(_,i)=>{let a=x+i%5-2,b=y+(i/5|0)-2;return a<0||b<0||a>9||b>9?1:+w[b*10+a]}),goal:[9-x,9-y],vis:dirs.map(([dx,dy])=>vis[(y+dy)*10+x+dx]||0),last}}
function features(o,a){const [dx,dy]=dirs[a];return[1,(dx*o.goal[0]+dy*o.goal[1])/18,Math.min(1,o.vis[a]/4),a===(o.last+2)%4?1:0,o.patch[(2+dy)*5+2+dx],o.patch[(2+2*dy)*5+2+2*dx]]}
export function fresh(){return{w:[0,0,0,0,0,0],cfg:{alpha:.015,eps:.2,penalty:.2},spent:0,train:0,validation:0,accepted:0,logs:[],history:[]}}
export function episode(agent,w,random,train=false,cap=120,fixed=false){let p=0,last=-10,vis=Array(100).fill(0),path=[0],repeats=0;for(let t=0;t<cap;t++){vis[p]++;const o=observe(w,p,vis,last),legal=dirs.map((_,a)=>a).filter(a=>!o.patch[(2+dirs[a][1])*5+2+dirs[a][0]]);let f=legal.map(a=>features(o,a)),q=f.map(v=>v.reduce((s,x,i)=>s+x*agent.w[i],0));const explore=train&&random()<agent.cfg.eps;let j=explore?Math.floor(random()*legal.length):0;if(!explore){for(let i=1;i<q.length;i++)if((fixed?f[i][1]-f[i][2]*2:q[i])>(fixed?f[j][1]-f[j][2]*2:q[j]))j=i}if(!legal.length)break;const a=legal[j],n=p+dirs[a][0]+10*dirs[a][1],repeat=vis[n]>0;repeats+=+repeat;const reward=n===99?10:-.05+(18-p%10-(p/10|0)-(18-n%10-(n/10|0)))*.1-agent.cfg.penalty*repeat;
if(train){const next=observe(w,n,vis,a);const qs=dirs.map((_,b)=>next.patch[(2+dirs[b][1])*5+2+dirs[b][0]]?-100:features(next,b).reduce((s,x,i)=>s+x*agent.w[i],0));const err=Math.max(-5,Math.min(5,reward+(n===99?0:.95*Math.max(...qs))-q[j]));agent.w=agent.w.map((v,i)=>Math.max(-20,Math.min(20,v+agent.cfg.alpha*err*f[j][i])))}p=n;last=a;path.push(p);if(p===99)break}return{success:p===99,steps:path.length-1,repeats,path}}
export function assess(a,seed,count=12,hard=false,fixed=false){let wins=0,steps=0,used=0;for(let i=0;i<count;i++){let r=episode(a,maze(seed+i,hard),rng(seed+i),false,120,fixed);wins+=+r.success;steps+=r.success?r.steps:0;used+=r.steps}return{rate:100*wins/count,avg:wins?steps/wins:null,used,score:wins*1000-steps/(wins||1)}}
function train(a,budget,seed){const r=rng(seed);let used=0;while(used<budget){let out=episode(a,maze(seed+used),r,true,Math.min(120,budget-used));a.repeatRate=out.repeats/Math.max(1,out.steps);used+=out.steps;if(!out.steps)break}a.train+=used;return used}
export function round(a,mode,seed){const allowance=5000;let used=0;if(mode==='fixed'){a.spent+=allowance;a.logs.push('固定规则，无训练；此轮额度未使用。')}else if(mode==='rl'){used=train(a,allowance-1440,seed);let v=assess(a,seed+200000);a.validation+=v.used;used+=v.used;used+=train(a,allowance-used,seed+40000);a.spent+=used;}else{const candidate=structuredClone(a),r=rng(seed);let field=mode==='random'?['alpha','eps','penalty'][Math.floor(r()*3)]:(a.repeatRate>.4?'penalty':a.history.length%2?'alpha':'eps');candidate.cfg[field]=field==='alpha'?[.005,.015,.04][Math.floor(r()*3)]:field==='eps'?[.1,.25,.45][Math.floor(r()*3)]:[.1,.4,.8][Math.floor(r()*3)];used+=train(candidate,1000,seed);used+=train(a,1000,seed);let old=assess(a,seed+200000,10),next=assess(candidate,seed+200000,10);used+=old.used+next.used;a.validation+=old.used+next.used;a.train+=1000;let keep=next.score>old.score;if(keep){a.w=candidate.w;a.cfg=candidate.cfg;a.accepted++}a.logs.push(`${field} → ${candidate.cfg[field]}；${keep?'保留':'拒绝'}；验证 ${old.rate.toFixed(0)}% → ${next.rate.toFixed(0)}%；试验消耗 ${used} 步`);used+=train(a,allowance-used,seed+40000);a.spent+=used}const v=assess(a,seed+600000,12,false,mode==='fixed'); // reporting evaluation charged separately and equally reserved
 a.validation+=v.used;a.spent=(a.history.length+1)*6440;a.history.push(v.rate);return v}
